mapper.insert:
INSERT INTO internship_progress_record
    (student_id, event_type, event_title, description, status, related_id, event_time, create_time)
SELECT ir.student_id, 'reflection_ai_failed', 'AI分析暂未完成',
       '心得已提交，AI分析暂未完成，可稍后重试或教师人工批阅，无需重复提交',
       CAST(#{version} AS CHAR), ir.id, #{failedAt}, #{failedAt}
FROM internship_reflection ir

LEFT JOIN (SELECT MAX(id) AS submission_version FROM internship_progress_record
           WHERE related_id = #{snapshot.id} AND student_id = #{snapshot.studentId}
             AND event_type IN ('reflection_submitted', 'reflection_resubmitted', 'reflection_submit', 'reflection_withdrawn')) latest ON 1 = 1
INNER JOIN (SELECT COUNT(*) AS failure_count FROM internship_progress_record
            WHERE related_id = #{snapshot.id} AND student_id = #{snapshot.studentId}
              AND event_type = 'reflection_ai_failed' AND status = CAST(#{version} AS CHAR)) failures ON 1 = 1
WHERE ir.id = #{snapshot.id} AND ir.student_id = #{snapshot.studentId}
  AND ir.deleted = 0 AND ir.status = 0 AND ir.remark IS NULL
  AND BINARY ir.content = BINARY #{snapshot.content}
  AND ir.submit_time = #{snapshot.submitTime}
  AND COALESCE(latest.submission_version, 0) = #{version}
  AND NOT EXISTS (SELECT 1 FROM student_reflection_ai_analysis analysis WHERE analysis.reflection_id = ir.id)
  AND NOT EXISTS (SELECT 1 FROM student_reflection_evaluation evaluation
                  WHERE evaluation.reflection_id = ir.id AND evaluation.total_score IS NOT NULL)
  AND failures.failure_count < 3

